-- ===== Veltrolib -> Noir bridge =====
do
    local __NC = NoirGenv().__NoirCore
    if __NC and __NC.host then
        local host = __NC.host
        local tabHost = host.CreateTab()
        local BULLET = string.char(226, 128, 162)
        local PAGE_FOR = {
            Stuff = "TRAIN", Gyms = "TRAIN", Rocks = "TRAIN", Rebirths = "TRAIN",
            Killing = "COMBAT",
            Home = "MISC", Stats = "MISC", Crystals = "MISC", Teleports = "MISC", Misc = "MISC", Settings = "MISC",
        }
        local function prefixFor(tabTitle)
            return (PAGE_FOR[tabTitle] or "MISC") .. " " .. BULLET .. " "
        end
        local function cbwrap(fn, ...)
            if type(fn) ~= "function" then return end
            local a = table.pack(...)
            task.spawn(function() pcall(fn, table.unpack(a, 1, a.n)) end)
        end
        local function dummyElem()
            return setmetatable({}, {
                __index = function() return function() return nil end end,
                __newindex = function() end,
            })
        end

        local nullDbg = (NoirGenv().__VeltroNullDebug == true)
        local function nullSectionApi(tag)
            tag = tag or "null"
            local elem = setmetatable({}, {
                __index = function(_, k)
                    return function(...)
                        if nullDbg then print("[NULLAPI] el." .. tostring(k)) end
                        return elem
                    end
                end,
                __newindex = function(self, k, v)
                    if nullDbg then print("[NULLAPI] el.__newindex " .. tostring(k)) end
                    rawset(self, k, v)
                end,
            })
            return setmetatable({}, {
                __index = function(_, m)
                    if m == "SetOpen" or m == "Open" or m == "Close" then
                        return function() return 0 end
                    end
                    if m == "SetTitles" then
                        return function(_, t)
                            if nullDbg then print("[NULLAPI] SetTitles -> " .. tostring(t)) end
                            return elem
                        end
                    end
                    return function(...)
                        if nullDbg then print("[NULLAPI] sec." .. tostring(m)) end
                        return elem
                    end
                end,
                __newindex = function(self, k, v)
                    if nullDbg then print("[NULLAPI] sec.__newindex " .. tostring(k)) end
                    rawset(self, k, v)
                end,
            })
        end

        local sectionWatch = {}
        NoirGenv().__VeltroSectionWatch = sectionWatch
        local function neuter(cfg)
            local copy = {}
            if type(cfg) == "table" then
                for k, v in pairs(cfg) do
                    if type(v) ~= "function" then copy[k] = v end
                end
            end
            return copy
        end
        local function buildSectionApi(section, tabName, killCb)
            local api = {}
            local watch = { section = section, count = 0 }
            sectionWatch[#sectionWatch + 1] = watch
            local function mark() watch.count += 1 end
            local function sane(cfg)
                cfg = type(cfg) == "table" and cfg or {}
                if killCb then cfg = neuter(cfg) end
                return cfg
            end

            function api:AddButton(cfg)
                cfg = sane(cfg)
            mark()
                local b = section:AddButton(tostring(cfg.Title or "Button"), function() cbwrap(cfg.Callback) end)
                local e = {}
                return setmetatable(e, { __index = function(_, k)
                    if k == "Instance" then return b end
                    return function() return nil end
                end, __newindex = function() end })
            end

            function api:AddToggle(cfg)
                cfg = sane(cfg)
            mark()
                VeltroLib.Flags[tostring(cfg.Flag or cfg.Title or "")] = cfg.Default == true
                local setter = section:AddToggle(tostring(cfg.Title or "Toggle"), function(v)
                    VeltroLib.Flags[tostring(cfg.Flag or cfg.Title or "")] = v == true
                    cbwrap(cfg.Callback, v)
                end)
                if cfg.Default == true then task.defer(function() pcall(setter, true) end) end
                local e = {}
                return setmetatable(e, { __index = function(_, k)
                    if k == "Set" or k == "SetValue" then
                        return function(_, v) pcall(setter, v == true) end
                    end
                    if k == "GetValue" then return function() return VeltroLib.Flags[tostring(cfg.Flag or cfg.Title or "")] == true end end
                    return function() return nil end
                end, __newindex = function() end })
            end

            function api:AddSlider(cfg)
                cfg = sane(cfg)
            mark()
                local min = tonumber(cfg.Min) or 0
                local max = tonumber(cfg.Max) or 100
                local ctl = section:AddSlider(tostring(cfg.Title or "Slider"), min, max, tonumber(cfg.Default) or min, function(v)
                    VeltroLib.Flags[tostring(cfg.Flag or cfg.Title or "")] = v
                    cbwrap(cfg.Callback, v)
                end)
                local e = {}
                return setmetatable(e, { __index = function(_, k)
                    if k == "Set" or k == "SetValue" then return function(_, v) if ctl and ctl.SetValue then ctl:SetValue(v) end end end
                    if k == "GetValue" then return function() return ctl and ctl.GetValue and ctl:GetValue() or 0 end end
                    return function() return nil end
                end, __newindex = function() end })
            end

            function api:AddTextBox(cfg)
                cfg = sane(cfg)
            mark()
                local ctl = section:AddTextBox(tostring(cfg.Title or cfg.Placeholder or "Value"), function(v)
                    VeltroLib.Flags[tostring(cfg.Flag or cfg.Title or "")] = v
                    cbwrap(cfg.Callback, v)
                end)
                if cfg.Default ~= nil then task.defer(function() pcall(function() ctl:SetValue(tostring(cfg.Default)) end) end) end
                local e = {}
                return setmetatable(e, { __index = function(_, k)
                    if k == "Set" or k == "SetValue" then return function(_, v) pcall(function() ctl:SetValue(tostring(v)) end) end end
                    return function() return nil end
                end, __newindex = function() end })
            end

            function api:AddDropdown(cfg)
                cfg = sane(cfg)
            mark()
                local opts = {}
                if type(cfg.Options) == "table" then
                    for _, v in ipairs(cfg.Options) do opts[#opts + 1] = tostring(v) end
                end
                local multi = cfg.MultiSelect == true
                local sel = {}
                local ctl = section:AddDropdown(tostring(cfg.Title or "Select"), #opts > 0 and opts or { "..." }, function(v)
                    task.spawn(function()
                        local arg = v
                        if multi then
                            if sel[v] then sel[v] = nil else sel[v] = true end
                            local arr = {}
                            for o in pairs(sel) do arr[#arr + 1] = o end
                            table.sort(arr)
                            arg = {}
                            for _, o in ipairs(arr) do arg[#arg + 1] = o arg[o] = true end
                        end
                        VeltroLib.Flags[tostring(cfg.Flag or cfg.Title or "")] = arg
                        if type(cfg.Callback) == "function" then pcall(cfg.Callback, arg) end
                    end)
                end)
                local e = {}
                return setmetatable(e, { __index = function(_, k)
                    if k == "Set" or k == "SetValue" then
                        return function(_, v)
                            pcall(function()
                                if type(v) == "table" then
                                    local arr = {}
                                    for _, o in ipairs(v) do arr[#arr + 1] = tostring(o) end
                                    if #arr == 0 then for o in pairs(v) do arr[#arr + 1] = tostring(o) end table.sort(arr) end
                                    if #arr > 0 then ctl:Refresh(arr, arr[1]) end
                                else
                                    ctl:SetValue(v)
                                end
                            end)
                        end
                    end
                    if k == "Refresh" then
                        return function(_, v)
                            pcall(function()
                                if type(v) == "table" then
                                    local arr = {}
                                    for _, o in ipairs(v) do arr[#arr + 1] = tostring(o) end
                                    ctl:ChangeItems(arr)
                                end
                            end)
                        end
                    end
                    return function() return nil end
                end, __newindex = function() end })
            end

            function api:AddLabel(cfg)
                cfg = type(cfg) == "table" and cfg or {}
            mark()
                local text0 = cfg.Text or cfg.Title or cfg or ""
                local lab = section:AddLabel(tostring(text0))
                local e = {}
                return setmetatable(e, { __index = function(_, k)
                    if k == "Set" or k == "SetValue" then return function(_, v) pcall(function() lab:SetValue(tostring(v)) end) end end
                    if k == "SetText" then return function(_, v) pcall(function() lab:SetValue(tostring(v)) end) end end
                    return function() return nil end
                end, __newindex = function() end })
            end

            function api:AddParagraph(cfg)
                cfg = type(cfg) == "table" and cfg or {}
            mark()
                local slots = {}
                local titleLab = section:AddLabel(tostring(cfg.Title or ""))
                local lineLabs = {}
                local e = {}
                local function apply(t)
                    if type(t) ~= "table" then return end
                    if t.Title then pcall(function() titleLab:SetValue(tostring(t.Title)) end) end
                    for i = 1, 12 do
                        local v = t["Text" .. i]
                        if v ~= nil and tostring(v) ~= "" then
                            if not lineLabs[i] then lineLabs[i] = section:AddLabel("") end
                            pcall(function() lineLabs[i]:SetValue(tostring(v)) end)
                        end
                    end
                end
                apply(cfg)
                return setmetatable(e, { __index = function(_, k)
                    if k == "Set" or k == "SetValue" then return function(_, v) apply(v) end end
                    return function() return nil end
                end, __newindex = function() end })
            end

            function api:AddDivider(cfg)
                mark()
                local t = cfg
                if type(t) == "table" then t = t[1] or t.Text or "" end
                section:AddLabel(tostring(t or ""))
                return dummyElem()
            end

            function api:AddDiscordInvite(cfg)
                return dummyElem()
            end

            return api
        end

        VeltroLib = {
            Flags = {},
            Themes = {},
            Instances = {},
            Elements = {},
        }
        setmetatable(VeltroLib, { __index = function() return function() return nil end end })

        local function makeElementWindow()
            local win = {}
            local tabCount = 0
            local sectionCountByTab = {}
            function win:MakeTab(cfg)
                cfg = type(cfg) == "table" and cfg or {}
                local tname = tostring(cfg.Title or "Tab")
                tabCount += 1
                local tab = {}
                function tab:AddSection(scfg)
                    scfg = type(scfg) == "table" and scfg or {}
                    local sname = tostring(scfg.Name or "Section")
                    local hidden = (tname == "Killing" and sname == "Spectate")
                    local section = tabHost:AddSection(prefixFor(tname) .. tname .. ": " .. sname, "")
                    local ok, api = pcall(buildSectionApi, section, tname, hidden)
                    if not ok then api = nullSectionApi(tname .. ":" .. sname) end
                    local w = sectionWatch[#sectionWatch]
                    if w then w.hidden = hidden end
                    if hidden then pcall(function() section.__panel.Visible = false end) end
                    return api
                end
                setmetatable(tab, { __index = function() return function() return dummyElem() end end })
                return tab
            end
            function win:Dialog(cfg)
                cfg = type(cfg) == "table" and cfg or {}
                pcall(function()
                    local t = tostring(cfg.Title or "Notice")
                    local b = tostring(cfg.Text or "")
                    host.Notify(t .. (b ~= "" and (" — " .. b) or ""), 4)
                end)
                return dummyElem()
            end
            local mt = { __index = function(_, k)
                -- AddTag / AddMinimizeButton / SetTheme etc: visible identity handled by Noir itself
                return function() return dummyElem() end
            end }
            setmetatable(win, mt)
            return win
        end

        function VeltroLib:MakeWindow(_cfg)
            return makeElementWindow()
        end
    end
end

-- ===== boot: run the harvested hub through the bridge =====
task.defer(function()
    local libReady = NoirGenv().__NoirCore and NoirGenv().__NoirCore.host
    if not libReady or not VeltroLib then return end
    local realLS = loadstring
    local realEnv = getfenv()
    local fakeEnv = setmetatable({}, {
        __index = function(_, k)
            if k == "loadstring" then
                return function(src, ...)
                    if type(src) == "string" and (string.find(src, "veltrolib", 1, true) or #src < 2000) then
                        -- substitute the whole UI library with the Noir bridge
                        return function() return VeltroLib end
                    end
                    return realLS(src, ...)
                end
            end
            return realEnv[k]
        end,
        __newindex = function(_, k, v) realEnv[k] = v end,
    })
    local bf, cerr = realLS(__ML_BLOB, "mlhub")
    if not bf then warn("[NoirML] blob compile failed: " .. tostring(cerr)) return end
    pcall(setfenv, bf, fakeEnv)
    local ok, err = pcall(bf)
    if not ok then warn("[NoirML] " .. tostring(err)) end
    -- hide sections that ended up with zero controls (dropped invite cards etc.)
    pcall(function()
        local watch = NoirGenv().__VeltroSectionWatch
        if type(watch) == "table" then
            for _, w in ipairs(watch) do
                if w.section and w.section.__panel and (w.count == 0 or w.hidden) then
                    pcall(function() w.section.__panel.Visible = false end)
                end
            end
        end
    end)
end)

-- ===== Noir open animation + runtime lock =====
task.defer(function()
    local core2 = NoirGenv().__NoirCore
    if not core2 then return end
    local win2, TweenService2 = core2.win, core2.TweenService
    if not (win2 and TweenService2) then return end
    task.wait(0.35)
    if not win2.Parent then return end
    local targetPosition = win2.Position
    win2.Position = targetPosition + UDim2.fromOffset(0, 32)
    win2.BackgroundTransparency = 1
    win2.Rotation = -1.2
    win2.Visible = true
    local scaleObj = win2:FindFirstChildWhichIsA("UIScale")
    if scaleObj then scaleObj.Scale = .68 end
    local openAlpha = .38
    pcall(function()
        local pers = core2.NoirPersistence
        if pers and pers.data and pers.data.sliders then
            openAlpha = tonumber(pers.data.sliders["Noir::WindowAlpha"]) or .38
        end
    end)
    TweenService2:Create(win2, TweenInfo.new(.56, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), { Position = targetPosition, BackgroundTransparency = openAlpha, Rotation = 0 }):Play()
    if scaleObj then
        TweenService2:Create(scaleObj, TweenInfo.new(.62, Enum.EasingStyle.Back, Enum.EasingDirection.Out), { Scale = 1 }):Play()
    end
end)
